% raylib typedefs these to structs already declared above; the
% bindings below just use the underlying name.
%   texture2d -> texture
%   texturecubemap -> texture
%   rendertexture2d -> rendertexture
%   camera -> camera3d

:- use_foreign_module('libraylib.so', [
	% ==== Window and Graphics Device Functions (Module: core) ====
	% Window-related functions
	'InitWindow'([sint,sint,cstr], void),                   % Initialize window and OpenGL context
	'CloseWindow'([], void),                                % Close window and unload OpenGL context
	'WindowShouldClose'([], bool),                          % Check if application should close (KEY_ESCAPE pressed or windows close icon clicked)
	'IsWindowReady'([], bool),                              % Check if window has been initialized successfully
	'IsWindowFullscreen'([], bool),                         % Check if window is currently fullscreen
	'IsWindowHidden'([], bool),                             % Check if window is currently hidden
	'IsWindowMinimized'([], bool),                          % Check if window is currently minimized
	'IsWindowMaximized'([], bool),                          % Check if window is currently maximized
	'IsWindowFocused'([], bool),                            % Check if window is currently focused
	'IsWindowResized'([], bool),                            % Check if window has been resized last frame
	'IsWindowState'([uint], bool),                          % Check if one specific window flag is enabled
	'SetWindowState'([uint], void),                         % Set window configuration state using flags
	'ClearWindowState'([uint], void),                       % Clear window configuration state flags
	'ToggleFullscreen'([], void),                           % Toggle window state: fullscreen/windowed, resizes monitor to match window resolution
	'ToggleBorderlessWindowed'([], void),                   % Toggle window state: borderless windowed, resizes window to match monitor resolution
	'MaximizeWindow'([], void),                             % Set window state: maximized, if resizable
	'MinimizeWindow'([], void),                             % Set window state: minimized, if resizable
	'RestoreWindow'([], void),                              % Restore window from being minimized/maximized
	'SetWindowIcon'([image], void),                         % Set icon for window (single image, RGBA 32bit)
	'SetWindowIcons'([ptr,sint], void),                     % Set icon for window (multiple images, RGBA 32bit)
	'SetWindowTitle'([cstr], void),                         % Set title for window
	'SetWindowPosition'([sint,sint], void),                 % Set window position on screen
	'SetWindowMonitor'([sint], void),                       % Set monitor for the current window
	'SetWindowMinSize'([sint,sint], void),                  % Set window minimum dimensions (for FLAG_WINDOW_RESIZABLE)
	'SetWindowMaxSize'([sint,sint], void),                  % Set window maximum dimensions (for FLAG_WINDOW_RESIZABLE)
	'SetWindowSize'([sint,sint], void),                     % Set window dimensions
	'SetWindowOpacity'([float], void),                      % Set window opacity [0.0f..1.0f]
	'SetWindowFocused'([], void),                           % Set window focused
	'GetWindowHandle'([], ptr),                             % Get native window handle
	'GetScreenWidth'([], sint),                             % Get current screen width
	'GetScreenHeight'([], sint),                            % Get current screen height
	'GetRenderWidth'([], sint),                             % Get current render width (it considers HiDPI)
	'GetRenderHeight'([], sint),                            % Get current render height (it considers HiDPI)
	'GetMonitorCount'([], sint),                            % Get number of connected monitors
	'GetCurrentMonitor'([], sint),                          % Get current monitor where window is placed
	'GetMonitorPosition'([sint], vector2),                  % Get specified monitor position
	'GetMonitorWidth'([sint], sint),                        % Get specified monitor width (current video mode used by monitor)
	'GetMonitorHeight'([sint], sint),                       % Get specified monitor height (current video mode used by monitor)
	'GetMonitorPhysicalWidth'([sint], sint),                % Get specified monitor physical width in millimetres
	'GetMonitorPhysicalHeight'([sint], sint),               % Get specified monitor physical height in millimetres
	'GetMonitorRefreshRate'([sint], sint),                  % Get specified monitor refresh rate
	'GetWindowPosition'([], vector2),                       % Get window position XY on monitor
	'GetWindowScaleDPI'([], vector2),                       % Get window scale DPI factor
	'GetMonitorName'([sint], ccstr),                        % Get the human-readable, UTF-8 encoded name of the specified monitor
	'SetClipboardText'([cstr], void),                       % Set clipboard text content
	'GetClipboardText'([], ccstr),                          % Get clipboard text content
	'GetClipboardImage'([], image),                         % Get clipboard image content
	'EnableEventWaiting'([], void),                         % Enable waiting for events on EndDrawing(), no automatic event polling
	'DisableEventWaiting'([], void),                        % Disable waiting for events on EndDrawing(), automatic events polling
	% Cursor-related functions
	'ShowCursor'([], void),                                 % Shows cursor
	'HideCursor'([], void),                                 % Hides cursor
	'IsCursorHidden'([], bool),                             % Check if cursor is not visible
	'EnableCursor'([], void),                               % Enables cursor (unlock cursor)
	'DisableCursor'([], void),                              % Disables cursor (lock cursor)
	'IsCursorOnScreen'([], bool),                           % Check if cursor is on the screen
	% Drawing-related functions
	'ClearBackground'([color], void),                       % Set background color (framebuffer clear color)
