	'EndDrawing'([], void),                                 % End canvas drawing and swap buffers (double buffering)
	'BeginMode2D'([camera2d], void),                        % Begin 2D mode with custom camera (2D)
	'EndMode2D'([], void),                                  % Ends 2D mode with custom camera
